func _initialize() -> void:
	for m in ["lighthouse", "keeper_house", "prop_boat", "prop_nets", "crab_armored"]:
		var n := (load("res://assets/models/%s.glb" % m) as PackedScene).instantiate() as Node3D
		root.add_child(n)
		for c in n.get_children():
			var box := _aabb(c, Transform3D.IDENTITY)
			print("%s/%s pos=%s min=%s max=%s" % [m, c.name, (c as Node3D).position, box.position, box.end])
		var all := _aabb(n, Transform3D.IDENTITY)
		print("ALL %s min=%s max=%s" % [m, all.position, all.end])
	quit(0)


func _aabb(n: Node, t: Transform3D) -> AABB:
	var res := AABB()
	var first := true
	var xf := t
	if n is Node3D:
		xf = t * (n as Node3D).transform
	if n is MeshInstance3D and (n as Node3D).visible:
		res = xf * (n as MeshInstance3D).get_aabb()
		first = false
	for c in n.get_children():
		var b := _aabb(c, xf)
		if b.size == Vector3.ZERO:
			continue
		if first:
			res = b
			first = false
		else:
			res = res.merge(b)
	return res

